// Appends Chemical Waving & Relaxing questions ids 282-331
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

const topic = `"Chemical Waving & Relaxing"`
const topic_es = `"Ondulación Química y Alisado"`
const psi_topic = `"Chemical Waving & Relaxing"`
const psi_topic_es = `"Ondulación Química y Alisado"`

const q = [
  { id: 282, question: "The size of the curl produced by a permanent wave is determined by:", question_es: "El tamaño del rizo producido por una permanente está determinado por:", options: ["The size of the perm rod used — smaller rods produce tighter curls; larger rods produce looser waves", "The pH of the waving lotion only", "The processing time — longer processing = tighter curl", "The porosity of the hair shaft"], options_es: ["El tamaño de la varilla de permanente usada — varillas más pequeñas producen rizos más apretados; varillas más grandes producen ondas más sueltas", "Solo el pH de la loción de ondulación", "El tiempo de procesamiento — más tiempo de procesamiento = rizo más apretado", "La porosidad del eje del cabello"], correct: 0, explanation: "The perm rod diameter directly determines curl size. Smaller rods (shorter circumference) = tighter, smaller curls; larger rods (larger circumference) = looser, larger waves. This is one of the most fundamental perm concepts." },
  { id: 283, question: "A 'concave rod' (also called a spot or circle rod) has:", question_es: "Una 'varilla cóncava' (también llamada varilla puntual o circular) tiene:", options: ["A smaller diameter in the center and larger at the ends, producing tighter curls at the midshaft and looser ends and roots", "An even diameter throughout its entire length", "A larger diameter in the center than at the ends", "A spiral groove running along its length"], options_es: ["Un diámetro más pequeño en el centro y más grande en los extremos, produciendo rizos más apretados en el punto medio y extremos y raíces más sueltos", "Un diámetro uniforme en toda su longitud", "Un diámetro más grande en el centro que en los extremos", "Una ranura en espiral a lo largo de su longitud"], correct: 0, explanation: "Concave rods have a smaller diameter in the middle and larger at each end. This creates a tighter, more defined curl at the midshaft and a slightly softer result at the roots and ends where the larger diameter wraps." },
  { id: 284, question: "A 'straight rod' (conventional rod) for perming has:", question_es: "Una 'varilla recta' (varilla convencional) para permanente tiene:", options: ["An even diameter throughout its entire length, producing a consistent curl size from root to end", "A tapered shape that is thicker at one end", "A spiral groove for directional curling", "A concave shape for more defined curl at the midshaft"], options_es: ["Un diámetro uniforme en toda su longitud, produciendo un tamaño de rizo consistente de raíz a punta", "Una forma ahusada que es más gruesa en un extremo", "Una ranura en espiral para rizado direccional", "Una forma cóncava para rizo más definido en el punto medio"], correct: 0, explanation: "Straight (conventional) perm rods have a consistent diameter throughout. They produce an even curl from root to end and are the most commonly used rod type for standard perming techniques." },
  { id: 285, question: "Spiral perm rods are designed to:", question_es: "Las varillas de permanente en espiral están diseñadas para:", options: ["Wind hair in a corkscrew pattern by rotating the rod vertically or at an angle, creating long, spiral curls that extend lengthwise", "Create tight ringlet curls on short hair only", "Produce a uniform wave pattern on all hair lengths", "Wrap hair horizontally for maximum volume at the root"], options_es: ["Enrollar el cabello en un patrón de sacacorchos girando la varilla verticalmente o en ángulo, creando rizos espirales largos que se extienden en longitud", "Crear rizos pequeños en cabello corto únicamente", "Producir un patrón de ondas uniforme en todas las longitudes de cabello", "Enrollar el cabello horizontalmente para máximo volumen en la raíz"], correct: 0, explanation: "Spiral rods (or using a standard rod placed vertically) wrap hair in a corkscrew/spring pattern from root to end, creating elongated spiral curls. This technique is used to create defined, long spiral curls on medium-to-long hair." },
  { id: 286, question: "An 'on-base' perm rod placement means:", question_es: "Una colocación de varilla de permanente 'en base' significa:", options: ["The rod sits directly on its base (the sectioned panel), resulting in maximum lift and volume at the root", "The rod sits halfway off its base, creating a balanced result", "The rod sits completely below its base section with no root lift", "The rod is positioned at a 45-degree angle to the scalp"], options_es: ["La varilla se sienta directamente en su base (el panel seccionado), resultando en máximo levantamiento y volumen en la raíz", "La varilla se sienta a mitad de su base, creando un resultado equilibrado", "La varilla se sienta completamente por debajo de su sección base sin levantamiento en la raíz", "La varilla se posiciona en un ángulo de 45 grados al cuero cabelludo"], correct: 0, explanation: "On-base placement: the rod is wound so it falls directly on its own base panel at 90+ degrees. This creates maximum root lift and volume, making the curl start at the scalp." },
  { id: 287, question: "An 'off-base' perm rod placement results in:", question_es: "Una colocación de varilla de permanente 'fuera de base' resulta en:", options: ["The rod sitting below its base (at 45 degrees or less), creating no root lift — the curl starts away from the scalp with a smooth root", "Maximum volume and lift at the root", "The rod sitting directly on its base for a standard result", "The rod angled 90 degrees upward from the scalp"], options_es: ["La varilla sentándose por debajo de su base (a 45 grados o menos), creando sin levantamiento en la raíz — el rizo comienza lejos del cuero cabelludo con una raíz suave", "Máximo volumen y levantamiento en la raíz", "La varilla sentándose directamente en su base para un resultado estándar", "La varilla angulada 90 grados hacia arriba del cuero cabelludo"], correct: 0, explanation: "Off-base placement: the rod is wound at below 45 degrees and sits below its base panel. This creates no root lift — the curl begins away from the scalp, giving a smooth root area. Used when volume at the root is not desired." },
  { id: 288, question: "The 'test curl' during perm processing is performed to:", question_es: "El 'rizo de prueba' durante el procesamiento de la permanente se realiza para:", options: ["Check whether the disulfide bonds have been sufficiently softened by unrolling a rod one to two turns and observing the resulting S-pattern", "Test if the neutralizer has been applied for long enough", "Check if the client's scalp is sensitive to the waving solution", "Determine if additional product needs to be applied"], options_es: ["Verificar si los enlaces disulfuro han sido suficientemente suavizados al desenrollar una varilla uno o dos giros y observar el patrón S resultante", "Verificar si el neutralizante ha sido aplicado el tiempo suficiente", "Verificar si el cuero cabelludo del cliente es sensible a la solución de ondulación", "Determinar si se necesita aplicar producto adicional"], correct: 0, explanation: "A test curl checks processing progress: unroll the rod 1-2 turns and check for an S-pattern. If the hair forms a clear 'S' shape, processing is complete. If the pattern is undefined or the hair doesn't hold shape, more processing time is needed." },
  { id: 289, question: "During a perm service, the waving lotion must be thoroughly rinsed before the neutralizer is applied because:", question_es: "Durante un servicio de permanente, la loción de ondulación debe enjuagarse completamente antes de aplicar el neutralizante porque:", options: ["Any remaining waving lotion (reducing agent) will react with and neutralize the neutralizer (oxidizer), preventing proper bond reformation", "The neutralizer works better on dry hair", "Rinsing first speeds up the neutralizer processing time", "The waving lotion would cause the curl to relax if left in contact with the neutralizer"], options_es: ["Cualquier loción de ondulación restante (agente reductor) reaccionará con y neutralizará el neutralizante (oxidante), previniendo la correcta reformación de los enlaces", "El neutralizante funciona mejor en cabello seco", "Enjuagar primero acelera el tiempo de procesamiento del neutralizante", "La loción de ondulación causaría que el rizo se relaje si queda en contacto con el neutralizante"], correct: 0, explanation: "Waving lotion (a reducing agent) and neutralizer (an oxidizing agent) are chemically opposite. If lotion remains when neutralizer is applied, they react with each other rather than reforming disulfide bonds in the hair, resulting in a poor perm." },
  { id: 290, question: "What role does hair porosity play in chemical waving services?", question_es: "¿Qué papel juega la porosidad del cabello en los servicios de ondulación química?", options: ["High-porosity hair absorbs chemicals faster, requiring shorter processing times or milder solutions; low-porosity hair resists penetration, requiring more processing time or a stronger formula", "Porosity does not affect chemical services", "High-porosity hair always requires a stronger perm solution regardless of hair condition", "Low-porosity hair always requires less processing time than high-porosity hair"], options_es: ["El cabello de alta porosidad absorbe los químicos más rápido, requiriendo tiempos de procesamiento más cortos o soluciones más suaves; el cabello de baja porosidad resiste la penetración, requiriendo más tiempo de procesamiento o una fórmula más fuerte", "La porosidad no afecta los servicios químicos", "El cabello de alta porosidad siempre requiere una solución de permanente más fuerte independientemente de la condición del cabello", "El cabello de baja porosidad siempre requiere menos tiempo de procesamiento que el cabello de alta porosidad"], correct: 0, explanation: "Porosity profoundly affects chemical services. High porosity (damaged cuticle) = fast absorption → risk of over-processing → use milder solutions and shorter times. Low porosity (tight cuticle) = slow absorption → may need heat or longer processing." },
  { id: 291, question: "An 'exothermic' perm is one that:", question_es: "Una permanente 'exotérmica' es aquella que:", options: ["Generates its own heat through a chemical reaction within the waving lotion, eliminating the need for an external heat source", "Requires external heat from a dryer or heat lamp to process", "Produces a cold reaction that must be offset with heat from a heat cap", "Uses an alkaline pH of 9.5 or higher exclusively"], options_es: ["Genera su propio calor a través de una reacción química dentro de la loción de ondulación, eliminando la necesidad de una fuente de calor externa", "Requiere calor externo de un secador o lámpara de calor para procesar", "Produce una reacción fría que debe compensarse con calor de una gorra de calor", "Usa un pH alcalino de 9.5 o más exclusivamente"], correct: 0, explanation: "Exothermic perms contain a heat-generating activator — when mixed with the waving lotion, a chemical reaction produces heat that helps process the perm without external heat. They typically process faster than regular cold waves." },
  { id: 292, question: "The 'cold wave' perm gets its name because:", question_es: "La permanente de 'onda fría' recibe su nombre porque:", options: ["It processes at room temperature without the application of external heat, unlike earlier methods that required heat", "It uses cold water rinse between the waving and neutralizing steps", "It produces a cool or tingling sensation on the scalp during processing", "The perm solution must be refrigerated before use"], options_es: ["Procesa a temperatura ambiente sin aplicación de calor externo, a diferencia de métodos anteriores que requerían calor", "Usa enjuague de agua fría entre los pasos de ondulación y neutralización", "Produce una sensación de frío o cosquilleo en el cuero cabelludo durante el procesamiento", "La solución de permanente debe refrigerarse antes del uso"], correct: 0, explanation: "Cold waves (modern thio perms) process at room temperature without external heat — in contrast to early permanent wave methods that required heat machines. 'Cold wave' simply means 'no heat required.'" },
  { id: 293, question: "When wrapping hair on perm rods, the hair strand should be:", question_es: "Al enrollar el cabello en las varillas de permanente, la hebra de cabello debe:", options: ["Wound smoothly and evenly around the rod with consistent tension — not too tight (which causes breakage) and not too loose (which creates frizz)", "Wound as tightly as possible to ensure maximum curl formation", "Wound loosely to prevent damage to the hair during processing", "Sprayed with waving lotion immediately before wrapping each rod"], options_es: ["Enrollado de manera suave y uniforme alrededor de la varilla con tensión constante — no demasiado apretado (lo que causa rotura) y no demasiado flojo (lo que crea frizz)", "Enrollado lo más apretado posible para garantizar la máxima formación de rizos", "Enrollado con soltura para prevenir daños al cabello durante el procesamiento", "Rociado con loción de ondulación inmediatamente antes de enrollar cada varilla"], correct: 0, explanation: "Perm rod wrapping requires even, consistent tension throughout. Too tight = hair is stretched over the rod edges, causing breakage. Too loose = hair doesn't conform uniformly to the rod shape, producing frizzy, undefined results." },
  { id: 294, question: "A 'bookend' or 'double flat wrap' perm technique uses:", question_es: "Una técnica de permanente 'bookend' o 'doble envoltura plana' usa:", options: ["End papers on both ends of the hair section — one folded under and one placed over the top — to smooth the ends and prevent 'fishhook' bends", "Two rods on each section for a tighter curl", "Papers only at the root end to protect the scalp", "A heated flat iron before rod placement"], options_es: ["Papeles de punta en ambos extremos de la sección de cabello — uno doblado por debajo y uno colocado encima — para alisar las puntas y prevenir dobleces en forma de anzuelo", "Dos varillas en cada sección para un rizo más apretado", "Papeles solo en el extremo de la raíz para proteger el cuero cabelludo", "Una plancha de cabello calentada antes de la colocación de la varilla"], correct: 0, explanation: "The bookend (double flat) wrap technique uses end papers placed on both sides (top and bottom) of the hair section ends. This completely encloses the ends, preventing them from folding back and creating unwanted 'fishhook' bends in the finished perm." },
  { id: 295, question: "Contraindications for performing a chemical relaxer service include:", question_es: "Las contraindicaciones para realizar un servicio de relajador químico incluyen:", options: ["Scalp abrasions, irritation, or open wounds; previously relaxed hair on the same day; and hair with severely poor elasticity", "Fine hair texture only", "Low-porosity hair", "Hair that has been shampooed within 48 hours"], options_es: ["Abrasiones del cuero cabelludo, irritación o heridas abiertas; cabello previamente relajado el mismo día; y cabello con elasticidad severamente deficiente", "Solo textura de cabello fino", "Cabello de baja porosidad", "Cabello que ha sido lavado en las últimas 48 horas"], correct: 0, explanation: "Contraindications for relaxer services: open scalp wounds/irritation (chemical burns are likely), hair with poor elasticity (will break), scalp sensitivity, recent prior chemical services on the same day, or incompatible prior chemical history." },
  { id: 296, question: "The primary purpose of end papers (perm end papers) in a perm service is to:", question_es: "El propósito principal de los papeles de punta (papeles de punta para permanente) en un servicio de permanente es:", options: ["Control the hair ends during rod wrapping, preventing them from folding back on themselves and creating bends or 'fish hooks' in the finished curl", "Protect the scalp from waving lotion drips", "Help the hair absorb more waving lotion for better processing", "Mark the parting sections on the head during wrapping"], options_es: ["Controlar las puntas del cabello durante el enrollado de la varilla, evitando que se doblen sobre sí mismas y creen dobleces o 'anzuelos' en el rizo terminado", "Proteger el cuero cabelludo de las gotas de loción de ondulación", "Ayudar al cabello a absorber más loción de ondulación para un mejor procesamiento", "Marcar las secciones de separación en la cabeza durante el enrollado"], correct: 0, explanation: "End papers (also called perm papers) are placed at the hair ends before wrapping around the perm rod. They prevent the fine ends from bending, folding, or 'fishhooking' as they wrap, ensuring smooth, even curl formation." },
  { id: 297, question: "How does a chemical relaxer permanently change the hair structure?", question_es: "¿Cómo cambia permanentemente un relajador químico la estructura del cabello?", options: ["By breaking and rearranging the disulfide bonds in the hair's cortex so the hair is restructured in a straightened position", "By coating the hair shaft with a smoothing layer that weighs it down", "By removing the cuticle layer from the hair shaft", "By temporarily stretching the cortex fibers into a straight position with heat"], options_es: ["Rompiendo y reorganizando los enlaces disulfuro en el córtex del cabello para que el cabello sea reestructurado en una posición alisada", "Recubriendo el eje del cabello con una capa alisadora que lo pesa", "Eliminando la capa de cutícula del eje del cabello", "Estirando temporalmente las fibras del córtex en una posición recta con calor"], correct: 0, explanation: "Chemical relaxers work by breaking the disulfide bonds in the cortex (the bonds responsible for the hair's curl pattern) and rearranging them in a straightened position (for hydroxide relaxers, this is lanthionization — a permanent, one-way change)." },
  { id: 298, question: "A 'virgin' hair application for a perm or relaxer differs from a retouch in that:", question_es: "Una aplicación de permanente o relajador en cabello 'virgen' difiere de un retoque en que:", options: ["Product is applied throughout the entire hair length from root to ends; retouch applies product only to the new growth", "Only the ends receive product in a virgin application", "A virgin application uses a milder chemical formula than a retouch", "A virgin application requires no strand test or skin test"], options_es: ["El producto se aplica en toda la longitud del cabello de raíz a puntas; el retoque aplica el producto solo al nuevo crecimiento", "Solo las puntas reciben el producto en una aplicación virgen", "Una aplicación virgen usa una fórmula química más suave que un retoque", "Una aplicación virgen no requiere prueba de mechón ni prueba de piel"], correct: 0, explanation: "A virgin application applies product to all previously untreated hair from root to end. A retouch applies product ONLY to the new growth since the last service, avoiding the previously treated hair to prevent overlapping and over-processing." },
  { id: 299, question: "Metallic salts in hair color (compound dye or metallic dye) are incompatible with chemical waving services because:", question_es: "Las sales metálicas en el color del cabello (tinte compuesto o tinte metálico) son incompatibles con los servicios de ondulación química porque:", options: ["They react violently with perm chemicals, causing excessive heat, hair breakage, or discoloration", "They prevent the perm solution from penetrating the hair shaft", "They cause the pH of the perm to become too acidic", "They neutralize the neutralizer, preventing proper bond reformation"], options_es: ["Reaccionan violentamente con los químicos de la permanente, causando calor excesivo, rotura del cabello o decoloración", "Evitan que la solución de permanente penetre en el eje del cabello", "Hacen que el pH de la permanente sea demasiado ácido", "Neutralizan el neutralizante, impidiendo la correcta reformación de los enlaces"], correct: 0, explanation: "Metallic salts (found in compound henna and some store-bought dyes) react with thio-based perm chemicals, causing violent reactions including excessive heat, discoloration, and severe hair breakage. Always perform an incompatibility test before chemical services." },
  { id: 300, question: "How long should a client typically wait between a relaxer service and a permanent color service on the same hair?", question_es: "¿Cuánto tiempo debe esperar generalmente un cliente entre un servicio de relajador y un servicio de color permanente en el mismo cabello?", options: ["At least 1–2 weeks (some protocols recommend waiting until after the next shampoo and recovery period before performing another chemical service)", "The services can be performed on the same day if done in the right order", "Only 48 hours between services is required", "There is no waiting period — these services are always compatible"], options_es: ["Al menos 1–2 semanas (algunos protocolos recomiendan esperar hasta después del próximo champú y período de recuperación antes de realizar otro servicio químico)", "Los servicios pueden realizarse el mismo día si se hacen en el orden correcto", "Solo se requieren 48 horas entre servicios", "No hay período de espera — estos servicios siempre son compatibles"], correct: 0, explanation: "Performing two major chemical services on the same day is generally contraindicated. Each chemical service stresses the hair. Most professionals recommend waiting at least 1-2 weeks between chemical services to allow the hair to stabilize and recover." },
  { id: 301, question: "Chemical waving or relaxing services should NOT be performed if the client:", question_es: "Los servicios de ondulación química o alisado NO deben realizarse si el cliente:", options: ["Has visible scalp abrasions, sores, or irritation in the service area", "Has color-treated hair with no damage", "Has medium hair texture with normal porosity", "Has never had a chemical service before"], options_es: ["Tiene abrasiones visibles del cuero cabelludo, llagas o irritación en el área de servicio", "Tiene cabello tratado con color sin daño", "Tiene textura de cabello medio con porosidad normal", "Nunca ha tenido un servicio químico antes"], correct: 0, explanation: "Any open wounds, sores, or scalp irritation are strict contraindications for chemical services. Applying caustic or strongly alkaline chemicals to broken skin causes chemical burns and significant client harm." },
  { id: 302, question: "The proper draping for chemical services (perm or relaxer) differs from a standard haircut draping because:", question_es: "El cubrimiento adecuado para servicios químicos (permanente o relajador) difiere del cubrimiento estándar para corte de cabello porque:", options: ["A waterproof (plastic) cape is used for chemical services to protect the client from chemical drips, while a cloth cape is used for cutting", "The chemical service cape is placed directly on the skin without a neck strip", "No cape is needed for perm services because the client's clothing is protected by the salon chair", "Only a towel draping is required for chemical services"], options_es: ["Se usa una capa impermeable (plástica) para servicios químicos para proteger al cliente de las gotas de químicos, mientras que una capa de tela se usa para el corte", "La capa del servicio químico se coloca directamente en la piel sin tira de cuello", "No se necesita capa para los servicios de permanente porque la ropa del cliente está protegida por la silla del salón", "Solo se requiere un cubrimiento con toalla para los servicios químicos"], correct: 0, explanation: "A waterproof plastic cape is essential for chemical services (perms, relaxers, color) to protect the client's clothing and skin from spills and drips of potentially caustic chemicals. The standard cloth cutting cape would absorb and hold chemicals." },
  { id: 303, question: "After completing a perm service and removing rods, the hair should be:", question_es: "Después de completar un servicio de permanente y quitar las varillas, el cabello debe:", options: ["Left in its natural curled state and handled minimally for the first 24–48 hours to allow the bonds to fully reform and set", "Blow-dried immediately with high heat to set the curl faster", "Wrapped tightly in a towel for 30 minutes", "Combed through with a fine-tooth comb to separate the curls"], options_es: ["Dejado en su estado rizado natural y manipulado mínimamente las primeras 24–48 horas para permitir que los enlaces se reformen completamente y se fijen", "Secado con secador inmediatamente con calor alto para fijar el rizo más rápido", "Envuelto apretadamente en una toalla durante 30 minutos", "Peinado con un peine de dientes finos para separar los rizos"], correct: 0, explanation: "After perming, newly formed disulfide bonds continue to stabilize for 24-48 hours. Clients should avoid washing, heat styling, or tying the hair for at least 24 hours (preferably 48) to allow bonds to fully harden in their new configuration." },
  { id: 304, question: "A neutralizing shampoo used after a relaxer service is formulated to:", question_es: "Un champú neutralizante usado después de un servicio de relajador está formulado para:", options: ["Have an acidic pH that counteracts the highly alkaline relaxer residue remaining in the hair, helping restore the hair to its normal pH range", "Deposit color into the hair shaft after relaxing", "Add protein to rebuild broken disulfide bonds", "Remove the protective base cream applied before the service"], options_es: ["Tener un pH ácido que contrarresta el residuo de relajador altamente alcalino que queda en el cabello, ayudando a restaurar el cabello a su rango de pH normal", "Depositar color en el eje del cabello después del alisado", "Añadir proteína para reconstruir los enlaces disulfuro rotos", "Eliminar la crema base protectora aplicada antes del servicio"], correct: 0, explanation: "After a highly alkaline relaxer, a neutralizing (acidic pH) shampoo is used to counteract residual alkalinity in the hair and scalp, helping restore the hair's natural slightly acidic pH (4.5-5.5) and stopping any remaining chemical action." },
  { id: 305, question: "Which test is used to determine if hair can withstand a chemical waving service?", question_es: "¿Qué prueba se usa para determinar si el cabello puede resistir un servicio de ondulación química?", options: ["Elasticity test — hair with poor elasticity (breaks immediately when stretched) may break under chemical processing stress", "Porosity test only", "Color test to check for metallic salts", "Density test to measure hair thickness"], options_es: ["Prueba de elasticidad — el cabello con elasticidad deficiente (se rompe inmediatamente cuando se estira) puede romperse bajo el estrés del procesamiento químico", "Solo prueba de porosidad", "Prueba de color para detectar sales metálicas", "Prueba de densidad para medir el grosor del cabello"], correct: 0, explanation: "The elasticity test is critical before chemical services. Hair that breaks with minimal stretch already has compromised disulfide bonds (the same bonds the chemical service will further stress). Such hair is at extreme risk of breakage during processing." },
  { id: 306, question: "Ammonium hydroxide in a perm solution acts as:", question_es: "El hidróxido de amonio en una solución de permanente actúa como:", options: ["An alkalizing agent that raises the pH and swells the hair cuticle, allowing the waving lotion to penetrate into the cortex", "The active reducing agent that breaks disulfide bonds", "The neutralizer that reforms disulfide bonds", "A conditioning agent to protect the hair during processing"], options_es: ["Un agente alcalinizante que eleva el pH e hincha la cutícula del cabello, permitiendo que la loción de ondulación penetre en el córtex", "El agente reductor activo que rompe los enlaces disulfuro", "El neutralizante que reforma los enlaces disulfuro", "Un agente acondicionador para proteger el cabello durante el procesamiento"], correct: 0, explanation: "Ammonium hydroxide (NH4OH) in perm formulas raises the pH and swells the cuticle scales, allowing the active reducing agent (ATG) to penetrate into the cortex where disulfide bonds are located. It is the alkaline 'vehicle' for the ATG." },
  { id: 307, question: "The recommended ventilation practice during chemical waving and relaxing services is:", question_es: "La práctica de ventilación recomendada durante los servicios de ondulación química y alisado es:", options: ["Working in a well-ventilated space to prevent buildup of fumes from ammonia and other volatile chemicals", "Closing all windows to maintain a consistent temperature for processing", "Turning off all fans to prevent air currents from affecting the chemical application", "Using extra heat to neutralize fumes before they reach the client"], options_es: ["Trabajar en un espacio bien ventilado para prevenir la acumulación de vapores de amoníaco y otros químicos volátiles", "Cerrar todas las ventanas para mantener una temperatura consistente para el procesamiento", "Apagar todos los ventiladores para evitar que las corrientes de aire afecten la aplicación química", "Usar calor adicional para neutralizar los vapores antes de que lleguen al cliente"], correct: 0, explanation: "Chemical perm and relaxer products release fumes (especially ammonia). Adequate ventilation is required for client and barber/stylist safety to prevent inhalation of chemical vapors that can cause respiratory irritation." },
  { id: 308, question: "What information should be documented on a chemical service record card?", question_es: "¿Qué información debe documentarse en una tarjeta de registro de servicio químico?", options: ["Client's hair analysis, product used, formula/strength, processing time, results, and any adverse reactions", "Only the client's name and the date of the service", "The cost of the service and payment method", "The barber's license number and the TDLR inspection date"], options_es: ["Análisis del cabello del cliente, producto usado, fórmula/resistencia, tiempo de procesamiento, resultados y cualquier reacción adversa", "Solo el nombre del cliente y la fecha del servicio", "El costo del servicio y el método de pago", "El número de licencia del barbero y la fecha de inspección de TDLR"], correct: 0, explanation: "Chemical service record cards must document: hair analysis results, products used (brand, formula, strength), processing time, results achieved, and any adverse reactions. This record protects the professional and guides future service decisions." },
  { id: 309, question: "Why should a scalp analysis be performed before any chemical relaxer service?", question_es: "¿Por qué debe realizarse un análisis del cuero cabelludo antes de cualquier servicio de relajador químico?", options: ["To identify contraindications such as scalp irritation, open wounds, or sensitivity that would make the service unsafe to perform", "To determine the client's hair color before bleaching", "To measure how much product will be needed", "To check if the client has recently used a competitor's product"], options_es: ["Para identificar contraindicaciones como irritación del cuero cabelludo, heridas abiertas o sensibilidad que harían el servicio inseguro de realizar", "Para determinar el color del cabello del cliente antes del aclarado", "Para medir cuánto producto se necesitará", "Para verificar si el cliente ha usado recientemente un producto de la competencia"], correct: 0, explanation: "Scalp analysis before a relaxer identifies any contraindications: open wounds, abrasions, inflammation, sensitivity, or active scalp conditions that make the service dangerous. Applying highly alkaline relaxer to damaged scalp causes severe burns." },
  { id: 310, question: "The correct order of steps in a basic alkaline cold wave perm is:", question_es: "El orden correcto de los pasos en una permanente de onda fría alcalina básica es:", options: ["Shampoo → section and wrap rods → apply waving lotion → process → rinse → neutralize → remove rods → rinse → style", "Apply waving lotion → shampoo → wrap rods → neutralize → rinse", "Wrap rods → neutralize → apply waving lotion → process → rinse", "Shampoo → apply waving lotion → rinse → wrap rods → neutralize"], options_es: ["Champú → seccionar y enrollar varillas → aplicar loción de ondulación → procesar → enjuagar → neutralizar → quitar varillas → enjuagar → peinar", "Aplicar loción de ondulación → champú → enrollar varillas → neutralizar → enjuagar", "Enrollar varillas → neutralizar → aplicar loción de ondulación → procesar → enjuagar", "Champú → aplicar loción de ondulación → enjuagar → enrollar varillas → neutralizar"], correct: 0, explanation: "Standard perm procedure: shampoo (no conditioner) → wrap rods with end papers → apply waving lotion → process (with test curl checks) → rinse thoroughly → apply neutralizer → leave on per instructions → remove rods → rinse again → condition and style." },
  { id: 311, question: "A 'weave' wrapping technique for perms involves:", question_es: "Una técnica de enrollado 'de trenzado' para permanentes implica:", options: ["Alternating rod placement in a brick-lay (staggered) pattern to prevent strong, visible part lines between sections in the finished curl", "Literally weaving strands over and under before wrapping on the rod", "Using two different rod sizes alternately across the same section", "Wrapping the hair in a diagonal direction only"], options_es: ["Alternando la colocación de las varillas en un patrón de ladrillo (escalonado) para evitar líneas de separación fuertes y visibles entre secciones en el rizo terminado", "Literalmente trenzar hebras por encima y por debajo antes de enrollarlas en la varilla", "Usar dos tamaños diferentes de varillas alternamente en la misma sección", "Enrollar el cabello en una dirección diagonal únicamente"], correct: 0, explanation: "Brick-lay (staggered or weave) wrapping alternates rod placement so no two rods share the same part line throughout the entire head. This eliminates visible 'laddering' (rows of straight part lines) in the finished perm result." },
  { id: 312, question: "If a client experiences scalp burning or severe discomfort during a relaxer service, the barber should:", question_es: "Si un cliente experimenta ardor del cuero cabelludo o malestar severo durante un servicio de relajador, el barbero debe:", options: ["Rinse the relaxer out immediately with cool or tepid water — do not wait for the processing time to complete", "Ask the client to wait a few more minutes to see if the sensation passes", "Apply more protective base cream over the relaxer", "Neutralize with shampoo without rinsing the relaxer first"], options_es: ["Enjuagar el relajador inmediatamente con agua fría o tibia — no esperar a que se complete el tiempo de procesamiento", "Pedir al cliente que espere unos minutos más para ver si la sensación desaparece", "Aplicar más crema base protectora sobre el relajador", "Neutralizar con champú sin enjuagar primero el relajador"], correct: 0, explanation: "Scalp burning during relaxer processing is a sign of chemical irritation or a chemical burn in progress. The relaxer must be rinsed out immediately with cool/tepid water (not hot — which opens blood vessels and increases absorption). Do not wait." },
  { id: 313, question: "Perm rods that are too small relative to the client's hair length can cause:", question_es: "Las varillas de permanente que son demasiado pequeñas en relación con la longitud del cabello del cliente pueden causar:", options: ["Difficulty wrapping (hair wraps multiple times, creating uneven stress) and an overly tight curl that may be too curly for the desired result", "A looser wave pattern than expected", "Faster processing time without any negative effects", "Better curl retention compared to appropriately sized rods"], options_es: ["Dificultad para enrollar (el cabello se envuelve varias veces, creando estrés desigual) y un rizo excesivamente apretado que puede ser demasiado rizado para el resultado deseado", "Un patrón de ondas más suelto de lo esperado", "Tiempo de procesamiento más rápido sin efectos negativos", "Mejor retención del rizo en comparación con varillas de tamaño apropiado"], correct: 0, explanation: "Rods that are too small cause the hair to wrap too many times, resulting in the hair being wound over itself. This creates uneven tension, potential breakage at stress points, and a tighter curl than desired." },
  { id: 314, question: "When should a barber NOT shampoo a client's hair immediately before applying a relaxer?", question_es: "¿Cuándo NO debe un barbero lavar el cabello de un cliente inmediatamente antes de aplicar un relajador?", options: ["When the scalp has no buildup — sebum (natural oils) on the scalp provides some protection against the caustic relaxer chemicals", "When the client has fine hair that tangles easily", "When the client requests coloring after the relaxer", "When using a no-base relaxer formula"], options_es: ["Cuando el cuero cabelludo no tiene acumulación — el sebo (aceites naturales) en el cuero cabelludo proporciona algo de protección contra los químicos cáusticos del relajador", "Cuando el cliente tiene cabello fino que se enreda fácilmente", "Cuando el cliente solicita coloración después del relajador", "Cuando se usa una fórmula de relajador sin base"], correct: 0, explanation: "The natural sebum on the scalp provides a thin protective barrier against the caustic relaxer. Shampooing just before a relaxer removes this barrier and can increase scalp sensitivity and irritation. Many protocols recommend shampooing 24-48 hours before." },
  { id: 315, question: "The purpose of a 'pre-wrap lotion' applied before winding perm rods is:", question_es: "El propósito de una 'loción pre-enrollado' aplicada antes de enrollar las varillas de permanente es:", options: ["To equalize hair porosity across the hair length so chemicals process more evenly, especially on hair with uneven porosity", "To replace the waving lotion on the perm rods", "To add curl pattern before the chemical is applied", "To protect the scalp from the waving lotion"], options_es: ["Igualar la porosidad del cabello a lo largo de la longitud del cabello para que los químicos procesen de manera más uniforme, especialmente en cabello con porosidad desigual", "Reemplazar la loción de ondulación en las varillas de permanente", "Añadir patrón de rizo antes de aplicar el químico", "Proteger el cuero cabelludo de la loción de ondulación"], correct: 0, explanation: "Pre-wrap lotion equalizes porosity along the hair shaft before perming. Uneven porosity causes chemicals to process faster in high-porosity areas (usually the ends) and slower in low-porosity areas (usually the roots), creating an uneven curl. Pre-wrap solution equalizes the surface." },
  { id: 316, question: "A 'reform perm' or 'curl reformation service' requires the hair to be:", question_es: "Una 'permanente de reforma' o 'servicio de reformación de rizos' requiere que el cabello esté:", options: ["In its natural (unprocessed) state or previously relaxed with a thio relaxer — NOT previously treated with a hydroxide relaxer", "Previously bleached to platinum before reforming", "Previously permed with an acid perm for best compatibility", "Processed with a hydroxide relaxer within the past 2 weeks for best bond receptivity"], options_es: ["En su estado natural (sin procesar) o previamente relajado con un relajador thio — NO previamente tratado con un relajador de hidróxido", "Previamente decolorado a platino antes de reformar", "Previamente permanentado con una permanente ácida para mejor compatibilidad", "Procesado con un relajador de hidróxido en las últimas 2 semanas para mejor receptividad de los enlaces"], correct: 0, explanation: "A curl reformation (soft curl perm) uses a two-step thio process. It can be performed on natural or thio-relaxed hair. It CANNOT be performed on hydroxide-relaxed hair because lanthionized bonds cannot be re-reduced with ATG — the chemistry is incompatible." },
  { id: 317, question: "After a permanent wave, when can the client safely shampoo their hair for the first time?", question_es: "Después de una permanente, ¿cuándo puede el cliente lavar su cabello de forma segura por primera vez?", options: ["At least 24–48 hours after the perm service to allow the newly reformed disulfide bonds to fully stabilize", "Immediately after leaving the salon — the bonds are set by the neutralizer", "After 1 week only — earlier washing destroys all curl", "After the hair is completely dry, which may take up to 72 hours"], options_es: ["Al menos 24–48 horas después del servicio de permanente para permitir que los enlaces disulfuro recién reformados se estabilicen completamente", "Inmediatamente después de salir del salón — los enlaces son fijados por el neutralizante", "Solo después de 1 semana — lavar antes destruye todo el rizo", "Después de que el cabello esté completamente seco, lo que puede tardar hasta 72 horas"], correct: 0, explanation: "Even after neutralization, disulfide bonds continue to harden and stabilize for 24-48 hours. Shampooing too soon (within 24 hours) can weaken the newly formed bonds, resulting in curl relaxation or a less defined final result." },
  { id: 318, question: "Scalp burns from a relaxer are most likely to occur when:", question_es: "Las quemaduras en el cuero cabelludo por un relajador son más probables cuando:", options: ["The scalp was scratched, abraded, or irritated before application; base cream was not applied; or the product was left on too long", "The relaxer was applied to very porous hair only", "The client has a very tight natural curl pattern", "The room temperature was too low during processing"], options_es: ["El cuero cabelludo fue rayado, abrasado o irritado antes de la aplicación; no se aplicó crema base; o el producto se dejó demasiado tiempo", "El relajador se aplicó solo a cabello muy poroso", "El cliente tiene un patrón de rizo natural muy apretado", "La temperatura de la habitación era demasiado baja durante el procesamiento"], correct: 0, explanation: "Chemical burns from relaxers are most common when: the scalp is already irritated/abraded (no natural protection), the barber scratched the scalp while sectioning, protective base cream was omitted, or the relaxer was left on beyond the recommended processing time." },
  { id: 319, question: "Which statement correctly describes an alkaline perm's pH range and processing characteristics?", question_es: "¿Qué enunciado describe correctamente el rango de pH de una permanente alcalina y sus características de procesamiento?", options: ["pH 8.5–9.5; processes at room temperature without additional heat; suitable for resistant or coarse hair", "pH 4.5–7.0; requires heat to process; best for fine, color-treated hair", "pH 12–14; processes extremely fast with intense heat; used only for very tight curls", "pH 7.0 (neutral); room temperature processing; for all hair types equally"], options_es: ["pH 8.5–9.5; procesa a temperatura ambiente sin calor adicional; adecuado para cabello resistente o grueso", "pH 4.5–7.0; requiere calor para procesar; mejor para cabello fino tratado con color", "pH 12–14; procesa extremadamente rápido con calor intenso; solo para rizos muy apretados", "pH 7.0 (neutro); procesamiento a temperatura ambiente; para todos los tipos de cabello igualmente"], correct: 0, explanation: "Alkaline (cold wave) perms: pH 8.5-9.5, process at room temperature (no heat needed), stronger action, better for resistant, coarse, or hard-to-wave hair. Acid perms: pH 4.5-7.0, require heat, gentler, better for fine/damaged/color-treated hair." },
  { id: 320, question: "For a client with previously color-treated (bleached) hair, which perm type is safer?", question_es: "Para un cliente con cabello previamente tratado con color (decolorado), ¿qué tipo de permanente es más seguro?", options: ["An acid-balanced perm (lower pH, gentler), because bleached hair is already highly porous and fragile", "An alkaline perm (higher pH), because it processes faster on porous hair", "A lye relaxer performed first to equalize the hair before perming", "A no-lye relaxer, because it is gentler than a perm"], options_es: ["Una permanente de pH ácido equilibrado (pH más bajo, más suave), porque el cabello decolorado ya es muy poroso y frágil", "Una permanente alcalina (pH más alto), porque procesa más rápido en cabello poroso", "Un relajador de lejía realizado primero para igualar el cabello antes de la permanente", "Un relajador sin lejía, porque es más suave que una permanente"], correct: 0, explanation: "Bleached hair is highly damaged, porous, and fragile. An acid-balanced perm (lower pH, gentler action) is safer because it is less likely to over-process or cause breakage compared to an alkaline perm on already-compromised hair." },
  { id: 321, question: "The process by which perm waving lotion (ATG) breaks disulfide bonds is called:", question_es: "El proceso por el cual la loción de ondulación de permanente (ATG) rompe los enlaces disulfuro se llama:", options: ["Reduction (the lotion is a reducing agent that donates hydrogen atoms to break S–S bonds)", "Oxidation (the lotion oxidizes the sulfur atoms)", "Lanthionization (permanent one-way bond conversion)", "Alkalization (the lotion raises pH to break ionic bonds)"], options_es: ["Reducción (la loción es un agente reductor que dona átomos de hidrógeno para romper los enlaces S–S)", "Oxidación (la loción oxida los átomos de azufre)", "Lantionización (conversión permanente unidireccional de enlaces)", "Alcalinización (la loción eleva el pH para romper los enlaces iónicos)"], correct: 0, explanation: "Waving lotion is a reducing agent — it reduces disulfide bonds by adding hydrogen (H) atoms to the sulfur atoms, breaking the S–S cross-links. This is called reduction. Neutralization then re-oxidizes (reforms) those bonds in the new shape." },
  { id: 322, question: "The Malone-Tobias method of analyzing perm results involves checking:", question_es: "El método Malone-Tobias de análisis de resultados de permanente implica verificar:", options: ["Curl development by gently unrolling a test rod and looking for a well-defined S-wave pattern in the released hair", "Whether the hair feels soft and slippery, indicating completion", "The color of the waving lotion residue in the hair", "The amount of heat generated by the exothermic reaction"], options_es: ["El desarrollo del rizo desenrollando suavemente una varilla de prueba y buscando un patrón de ondas S bien definido en el cabello liberado", "Si el cabello se siente suave y resbaladizo, indicando que está completo", "El color del residuo de la loción de ondulación en el cabello", "La cantidad de calor generada por la reacción exotérmica"], correct: 0, explanation: "The standard perm test curl check: unroll a test rod one to two turns, and look for a clear S-wave pattern. A well-defined S indicates sufficient processing. Incomplete or undefined pattern = needs more time. Over-processed = S is too tight or hair feels mushy." },
  { id: 323, question: "Which factor helps determine how many perm rods are needed for a given haircut?", question_es: "¿Qué factor ayuda a determinar cuántas varillas de permanente se necesitan para un corte de cabello dado?", options: ["The head size, hair density, rod size chosen, and the sectioning method used — more rods cover more area for thicker or larger heads", "Only the client's hair length", "Only the pH of the waving lotion selected", "The brand of neutralizer to be used"], options_es: ["El tamaño de la cabeza, la densidad del cabello, el tamaño de la varilla elegida y el método de sección usado — más varillas cubren más área para cabezas más gruesas o grandes", "Solo la longitud del cabello del cliente", "Solo el pH de la loción de ondulación seleccionada", "La marca del neutralizante a usar"], correct: 0, explanation: "The number of rods needed depends on head size, hair density, rod diameter (smaller rods = more rods needed to cover the same area), and sectioning method. These factors must be considered when ordering supplies and planning the service." },
  { id: 324, question: "Overprocessed hair from a perm typically feels:", question_es: "El cabello sobreprocesado de una permanente típicamente se siente:", options: ["Mushy, gummy, or frizzy when wet, and very dry and brittle when dry, indicating excessive bond breakage", "Silky and smooth with tight, defined curls", "Stiff and hard to the touch with excessive curl", "Completely normal — overprocessing only affects color, not texture"], options_es: ["Blanduzco, gomoso o con frizz cuando está húmedo, y muy seco y quebradizo cuando está seco, indicando rotura excesiva de enlaces", "Sedoso y suave con rizos apretados y definidos", "Rígido y duro al tacto con rizos excesivos", "Completamente normal — el sobreprocesamiento solo afecta el color, no la textura"], correct: 0, explanation: "Overprocessed perm hair has had too many disulfide bonds broken. When wet it feels mushy, gummy, or spongy — when dry it is frizzy and brittle. This damage is irreversible; the damaged portions must eventually be cut off." },
  { id: 325, question: "Which of the following would be the BEST perm rod size for creating soft, beach-wave style curls on shoulder-length hair?", question_es: "¿Cuál de los siguientes sería el MEJOR tamaño de varilla de permanente para crear rizos suaves de estilo playa en cabello a la altura de los hombros?", options: ["Large or extra-large rods (to create a loose, relaxed wave rather than tight ringlets)", "Small or miniature rods (for tight ringlet curls)", "Medium rods only (the standard choice for all curl types)", "No rods — beach waves cannot be achieved with a traditional perm"], options_es: ["Varillas grandes o extragrandes (para crear una onda suelta y relajada en lugar de rizos apretados)", "Varillas pequeñas o miniatura (para rizos apretados)", "Solo varillas medianas (la elección estándar para todos los tipos de rizo)", "Sin varillas — las ondas de playa no se pueden lograr con una permanente tradicional"], correct: 0, explanation: "Larger rods create looser, larger waves — ideal for beach-wave or 'body wave' looks. Smaller rods create tighter ringlet curls. Choosing large rods on shoulder-length hair creates the loose, natural-looking wave pattern associated with beach waves." },
  { id: 326, question: "A chemical service record must be kept primarily to:", question_es: "Un registro de servicio químico debe mantenerse principalmente para:", options: ["Ensure consistent results, track adverse reactions, document formulas used, and provide a legal record protecting both the professional and client", "Satisfy TDLR inspection requirements only", "Track the financial profitability of chemical services", "Determine which products to reorder"], options_es: ["Garantizar resultados consistentes, rastrear reacciones adversas, documentar las fórmulas usadas y proporcionar un registro legal que proteja tanto al profesional como al cliente", "Satisfacer solo los requisitos de inspección de TDLR", "Rastrear la rentabilidad financiera de los servicios químicos", "Determinar qué productos reordenar"], correct: 0, explanation: "Chemical service records are essential for: reproducing successful results, avoiding repeating failures, identifying patterns in adverse reactions, documenting informed consent, and providing a legal defense if a client claims injury." },
  { id: 327, question: "A barber performing a perm should avoid applying waving lotion directly to the scalp because:", question_es: "Un barbero que realiza una permanente debe evitar aplicar la loción de ondulación directamente en el cuero cabelludo porque:", options: ["It can cause scalp irritation or chemical burns, as perm lotion is formulated for the hair shaft, not the sensitive scalp skin", "It would make the perm process too quickly", "The scalp absorbs the lotion, reducing the amount available for the hair", "TDLR regulations prohibit perm lotion contact with the scalp"], options_es: ["Puede causar irritación del cuero cabelludo o quemaduras químicas, ya que la loción de permanente está formulada para el eje del cabello, no para la sensible piel del cuero cabelludo", "Haría que la permanente procese demasiado rápido", "El cuero cabelludo absorbe la loción, reduciendo la cantidad disponible para el cabello", "Las regulaciones de TDLR prohíben el contacto de la loción de permanente con el cuero cabelludo"], correct: 0, explanation: "Perm waving solutions can irritate the sensitive scalp skin. Application should begin at least 1/4 to 1/2 inch from the scalp. Scalp contact can cause inflammation, chemical burns, or an adverse reaction." },
  { id: 328, question: "The term 'over-directed' perm refers to:", question_es: "El término de permanente 'sobre-dirigida' se refiere a:", options: ["Wrapping hair onto rods at an angle that directs curl toward a specific area — used for design purposes to direct curl flow in a particular direction", "Using rods that are too large for the hair length", "Applying too much waving lotion to the rods", "Wrapping hair in a way that overlaps from one section into another"], options_es: ["Enrollar el cabello en varillas en un ángulo que dirige el rizo hacia un área específica — usado con fines de diseño para dirigir el flujo del rizo en una dirección particular", "Usar varillas que son demasiado grandes para la longitud del cabello", "Aplicar demasiada loción de ondulación en las varillas", "Enrollar el cabello de una manera que se superpone de una sección a otra"], correct: 0, explanation: "Over-directed perm rod placement intentionally angles rods toward a specific direction, causing the resulting curl to flow in that direction. This is a design tool used to direct waves or curls toward the face, backward, or in a particular pattern." },
  { id: 329, question: "Which of the following correctly explains why perming and coloring should not be performed on the same day?", question_es: "¿Cuál de los siguientes explica correctamente por qué la permanente y la coloración no deben realizarse el mismo día?", options: ["Both services involve opening the cuticle and stressing the hair — performing both the same day can cause severe damage, breakage, and unpredictable color results", "Chemical perm solution neutralizes hair dye, making color services impossible the same day", "TDLR rules prohibit performing two chemical services in the same appointment", "Color and perm solutions are always incompatible and will cause an explosion if mixed"], options_es: ["Ambos servicios implican abrir la cutícula y estresar el cabello — realizar ambos el mismo día puede causar daño severo, rotura y resultados de color impredecibles", "La solución de permanente química neutraliza el tinte del cabello, haciendo imposibles los servicios de color el mismo día", "Las reglas de TDLR prohíben realizar dos servicios químicos en la misma cita", "Las soluciones de color y permanente son siempre incompatibles y causarán una explosión si se mezclan"], correct: 0, explanation: "Both perm and color services involve processing agents that stress, open, and alter the hair. Combining both on the same day dramatically increases the risk of severe damage, breakage, and unpredictable or uneven color results. Allow at least one week between services." },
  { id: 330, question: "When the perm neutralizer is applied to the rods, it should be:", question_es: "Cuando el neutralizante de permanente se aplica a las varillas, debe:", options: ["Applied generously and evenly to all rods, ensuring complete saturation, and left on for the full manufacturer-specified time (usually 5–10 minutes) before removing rods", "Applied quickly and rods removed immediately", "Applied for 2 minutes maximum and then rinsed", "Applied only to the ends of the hair that extend beyond the rods"], options_es: ["Aplicado de manera generosa y uniforme en todas las varillas, asegurando saturación completa, y dejado por el tiempo completo especificado por el fabricante (generalmente 5–10 minutos) antes de quitar las varillas", "Aplicado rápidamente y las varillas se quitan inmediatamente", "Aplicado por un máximo de 2 minutos y luego enjuagado", "Aplicado solo a las puntas del cabello que se extienden más allá de las varillas"], correct: 0, explanation: "Proper neutralization requires complete saturation of all rods and the full manufacturer-recommended contact time (typically 5-10 minutes on the rods). Insufficient neutralization means disulfide bonds are incompletely reformed — resulting in a weak, poorly defined curl that relaxes quickly." },
  { id: 331, question: "A 'body wave' perm differs from a traditional tight-curl perm in that a body wave:", question_es: "Una permanente de 'onda suave' difiere de una permanente de rizo apretado tradicional en que una onda suave:", options: ["Uses larger rods to create loose, voluminous waves with body rather than tight ringlets, often processed for less time", "Requires a stronger waving solution than a tight perm", "Uses the same rod sizes as a tight perm but with shorter processing time only", "Is performed only on already-curly hair to relax the pattern slightly"], options_es: ["Usa varillas más grandes para crear ondas sueltas y voluminosas con cuerpo en lugar de rizos apretados, a menudo procesadas por menos tiempo", "Requiere una solución de ondulación más fuerte que una permanente apretada", "Usa los mismos tamaños de varilla que una permanente apretada pero solo con menos tiempo de procesamiento", "Se realiza solo en cabello ya rizado para relajar el patrón ligeramente"], correct: 0, explanation: "A body wave uses large-diameter rods and is often processed for a shorter time to create loose, relaxed waves with body and movement — not tight curls. The result adds volume and wave without defining ringlets." },
]

function fmt(q) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${psi_topic}, psi_topic_es: ${psi_topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const lines = q.map(fmt).join('\n')
const existing = readFileSync(FILE, 'utf8')
writeFileSync(FILE, existing + lines + '\n', 'utf8')
console.log(`Appended ${q.length} Chemical Waving questions (ids ${q[0].id}–${q[q.length-1].id})`)
